    const d = await r.json();
    if (!r.ok || !d.success) { status.textContent = d.errorMessage || '\u5220\u9664\u5931\u8D25'; return; }
    status.textContent = '\u5DF2\u5220\u9664\u5F39\u5E55\u6587\u4EF6';
